<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $project = App\Models\Project::find(1); $c = App\Models\Component::whereHas('mold', function($q) use ($project) { $q->where('project_id', $project->id); })->select('category_id', DB::raw('SUM(stock * unit_price) as cost'))->groupBy('category_id')->get()->map(function($i) { return ['category' => $i->category_id ? App\Models\ComponentCategory::find($i->category_id)->name ?? 'Uncategorized' : 'Uncategorized', 'cost' => (float) $i->cost]; })->sortByDesc('cost')->values(); echo json_encode(['labels' => $c->pluck('category'), 'data' => $c->pluck('cost')]);
